void motor_forward(int speed) {
    digitalWrite({{in1}}, HIGH);
    digitalWrite({{in2}}, LOW);
    analogWrite({{pwm_pin}}, speed);
}
void motor_reverse(int speed) {
    digitalWrite({{in1}}, LOW);
    digitalWrite({{in2}}, HIGH);
    analogWrite({{pwm_pin}}, speed);
}
void motor_stop() {
    digitalWrite({{in1}}, LOW);
    digitalWrite({{in2}}, LOW);
}
